  //                    (CONFIG.ALLOWED_APPROVERS still applies as well.)
  //   timeout_minutes: default wait before auto-decline. null = CONFIG.DEFAULT_TIMEOUT_MINUTES.
  //   self_approval:   false = the requester may NOT approve their own request of this type. null = follow CONFIG.
  //   prompt_fields:   which keys of "details" appear in the Slack message. null = show all of them.
  //   required_approvals: how many DIFFERENT people must approve before the action runs (1 to 10, default 1).
  //                    One deny from an allowed approver ends it at once. Needs CONFIG.APPROVER_API_TOKEN or
  //                    CONFIG.SLACK_SIGNING_SECRET when above 1. If it times out first, nothing runs.
  //   escalate_after_minutes + escalate_to: if still pending after this long, tell these people (and ops in Slack).
  //                    When approvers is set, they may also approve from that moment. null / [] = no escalation.
  default: { approvers: [], timeout_minutes: null, self_approval: null, prompt_fields: null, required_approvals: 1, escalate_after_minutes: null, escalate_to: [] },

  by_action_type: {
    // refund: { approvers: ['alice', 'carol'], timeout_minutes: 30, self_approval: false, prompt_fields: ['order_id', 'reason'] },
    // payout: { approvers: ['alice', 'carol', 'erin'], required_approvals: 2, timeout_minutes: 120, escalate_after_minutes: 30, escalate_to: ['dana'] },
  },

  // What requesters (and escalation contacts) are told. Use {action_type} {action_id} {responder} {requested_by}.
  // (Alerts to ops are fixed on purpose and cannot be changed or switched off here.)
  messages: {
    requester_denied: 'Your request "{action_type}" ({action_id}) was denied by {responder}. Nothing was executed.',
    requester_executed: 'Your request "{action_type}" ({action_id}) was approved by {responder} and executed.',
    requester_timeout: 'Your request "{action_type}" ({action_id}) was not approved in time and has been auto-declined. Nothing was executed.',
    escalation: 'Escalated to you: "{action_type}" ({action_id}) requested by {requested_by} is still waiting for a decision.',
  },
