const pick = (o, k, d) => (o && o[k] !== undefined && o[k] !== null ? o[k] : d);
const norm = { allowed_action_types: pick(policy, 'allowed_action_types', []), default: pick(policy, 'default', {}), by_action_type: pick(policy, 'by_action_type', {}), messages: pick(policy, 'messages', {}) };
