const store = base(C.APPROVAL_STORE_API_URL);
const max = Number(C.RECONCILE_MAX_PER_RUN), staleSec = Number(C.RECONCILE_STALE_SECONDS);
const rep = { expired: [], expire_skipped: [], executed: [], execution_failed: [], execution_unknown: [], not_executed: [], underapproved: [], skipped: [], problems: [] };
const requesterNotes = [], opsNotes = [];
const listOf = (r) => (r.status === 200 && r.body && Array.isArray(r.body.approvals) ? r.body.approvals : null);

// ---- 1. requests still pending after their deadline (the timer was lost, for example because n8n was down): auto-decline them
if (C.RECONCILE_EXPIRE) {
  const l = listOf(await call('GET', `${store}/approvals?status=pending&expired=true&limit=${max}`));
  if (l === null) rep.problems.push('the approval store could not list expired requests');
  else {
    // do not trust the store's filtering: only a request that is really pending and really past its deadline is touched
    const due = l.filter((x) => isObj(x) && idOk(x.action_id) && x.status === 'pending' && Date.parse(x.expires_at) <= Date.now()).slice(0, max);
    for (const rec of due) {
      const x = await call('POST', `${store}/approvals/${enc(rec.action_id)}/resolve`, { decision: 'timeout', resolved_by: 'system_timeout' });
      if (x.status === 200 && x.body && x.body.claimed === true) {
        rep.expired.push(rec.action_id);
        requesterNotes.push({ kind: 'requester', to: rec.requested_by, text: fillMsg(MSG.requester_timeout, { action_type: rec.action_type, action_id: rec.action_id, responder: 'system_timeout', requested_by: rec.requested_by }) });
      } else if (x.status === 409) rep.expire_skipped.push(rec.action_id);
      else rep.problems.push(`could not auto-decline ${rec.action_id} (${why(x)})`);
    }
  }
}

// ---- 2. approved, but never run (n8n died between recording the decision and running the action)
const l2 = listOf(await call('GET', `${store}/approvals?status=approved&unexecuted=true&older_than_seconds=${staleSec}&limit=${max}`));
if (l2 === null) rep.problems.push('the approval store could not list approved requests without an execution');
else {
  const cand = l2.filter((x) => isObj(x) && idOk(x.action_id) && x.status === 'approved' && !x.execution && Date.now() - Date.parse(x.resolved_at) >= staleSec * 1000).slice(0, max);
  for (const rec of cand) {
    const rule = Object.prototype.hasOwnProperty.call(PL.by_action_type, rec.action_type) ? PL.by_action_type[rec.action_type] : PL.default;
    const need = Math.max(1, Number(rec.required_approvals) || 1, Number(rule.required_approvals) || 1);   // never less than the policy says
    const votes = Array.isArray(rec.approvals) ? new Set(rec.approvals.map((a) => String(a && a.by).toLowerCase())).size : 0;
    if (need > 1 && votes < need) { rep.underapproved.push(rec.action_id); continue; }
    if (!C.RECONCILE_EXECUTE) { rep.not_executed.push(rec.action_id); continue; }
    // claim it (atomic) so two reconcile runs, or a run and a person, can never run the same action
    const c = await call('POST', `${store}/approvals/${enc(rec.action_id)}/execution-claim`, { lease_seconds: staleSec });
    const won = c.status === 200 && c.body && c.body.claimed === true;
    if (!won || !isObj(c.body.record) || c.body.record.action_id !== rec.action_id || c.body.record.status !== 'approved' || c.body.record.execution) { rep.skipped.push(rec.action_id); continue; }
    const r0 = c.body.record;
    const all = Array.isArray(r0.approvals) && r0.approvals.length ? r0.approvals.map((a) => String(a.by)) : [String(r0.resolved_by)];
    const ex = await call('POST', base(C.ACTION_EXECUTOR_API_URL) + '/execute', { action_id: r0.action_id, action_type: r0.action_type, details: r0.details, amount: r0.amount, approved_by: String(r0.resolved_by), approved_by_all: all, idempotency_key: 'approval:' + r0.action_id }, Number(C.EXECUTOR_TIMEOUT_MS));
    const good = typeof ex.status === 'number' && ex.status >= 200 && ex.status < 300;
    const unknown = typeof ex.status !== 'number';
    const status = good ? 'executed' : unknown ? 'unknown' : 'failed';
    const detail = good ? '' : unknown ? 'no response from the executor: ' + String(ex.error || 'timeout').slice(0, 160) : 'HTTP ' + ex.status;
    const rr = await call('POST', `${store}/approvals/${enc(r0.action_id)}/execution`, { status, detail, via: 'reconcile' });
    if (!(rr.status !== null && rr.status < 300)) rep.problems.push(`${r0.action_id}: the execution outcome could not be recorded in the approval store (${why(rr)})`);
    if (good) {
      rep.executed.push(r0.action_id);
      requesterNotes.push({ kind: 'requester', to: r0.requested_by, text: fillMsg(MSG.requester_executed, { action_type: r0.action_type, action_id: r0.action_id, responder: all.length > 1 ? all.slice(0, -1).join(', ') + ' and ' + all[all.length - 1] : all[0], requested_by: r0.requested_by }) });
    } else {
      (unknown ? rep.execution_unknown : rep.execution_failed).push(r0.action_id);
      requesterNotes.push({ kind: 'requester', to: r0.requested_by, text: unknown
        ? `Your request "${r0.action_type}" (${r0.action_id}) was approved, but we did not get a response from the executor, so the result is unknown. Ops has been alerted.`
        : `Your request "${r0.action_type}" (${r0.action_id}) was approved, but executing it failed (${detail}). Ops has been alerted.` });
      opsNotes.push(unknown
        ? `ATTENTION: approved action ${r0.action_id} (${r0.action_type}): executor gave NO response when reconcile re-ran it (${detail}). It may or may not have run. Idempotency key: approval:${r0.action_id}.`
        : `ATTENTION: approved action ${r0.action_id} (${r0.action_type}) FAILED when reconcile re-ran it (${detail}). Idempotency key: approval:${r0.action_id}.`);
    }
  }
}
const mins = Math.round(staleSec / 60);
const lines = [];
if (rep.problems.length) lines.push('Reconcile problem: ' + rep.problems.join('; ') + '.');
if (rep.expired.length) lines.push(`Reconcile auto-declined ${rep.expired.length} request(s) that were still pending after their deadline: ${rep.expired.join(', ')}.`);
if (rep.executed.length) lines.push(`Reconcile ran ${rep.executed.length} approved action(s) that had never run: ${rep.executed.join(', ')}.`);
if (rep.not_executed.length) lines.push(`${rep.not_executed.length} approved action(s) have no execution recorded after ${mins}+ minutes: ${rep.not_executed.join(', ')}. RECONCILE_EXECUTE is off, so nothing was run. Check them.`);
if (rep.underapproved.length) lines.push(`ATTENTION: ${rep.underapproved.length} action(s) are marked approved with fewer approvals than the policy requires: ${rep.underapproved.join(', ')}. They were NOT executed.`);
const notifications = [...requesterNotes, ...(lines.length ? [{ kind: 'slack', text: lines.join(' ') }] : []), ...opsNotes.map((t) => ({ kind: 'slack', text: t }))];
return [{ json: { ok: true, http_status: 200, response_body: { status: rep.problems.length ? 'incomplete' : 'ok', expire: C.RECONCILE_EXPIRE, execute: C.RECONCILE_EXECUTE, ...rep }, notifications } }];

const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const C = $('CONFIG').first().json;
const list = $input.first().json.notifications || [];
const out = [];
for (const n of list) {
  if (n.kind === 'slack' && C.SLACK_WEBHOOK_URL) out.push({ json: { kind: 'slack', text: '[Approvals] ' + esc(n.text) } });
  if (n.kind === 'requester' && C.NOTIFY_API_URL && n.to) out.push({ json: { kind: 'requester', to: n.to, text: n.text } });
}
return out;
